/**
 * Maps model ID or provider name to its corresponding branded icon
 */
export function getProviderIcon(id: string, size: number = 13): React.ReactNode {
  const p = id.toLowerCase();
  if (p.includes("anthropic") || p.includes("claude")) {
    return <ClaudeIcon size={size} />;
  }
  if (p.includes("openai") || p.includes("gpt") || p.includes("whisper-1")) {
    return <OpenAIIcon size={size} />;
  }
  if (p.includes("deepseek")) {
    return <DeepSeekIcon size={size} />;
  }
  if (p.includes("google") || p.includes("gemini")) {
    return <GeminiIcon size={size} />;
  }
  if (p.includes("x-ai") || p.includes("xai") || p.includes("grok")) {
    return <GrokIcon size={size} />;
  }
  if (p.includes("qwen") || p.includes("alibaba")) {
    return <QwenIcon size={size} />;
  }
  if (p.includes("meta") || p.includes("llama")) {
    return <MetaIcon size={size} />;
  }
  if (p.includes("mistral")) {
    return <MistralIcon size={size} />;
  }
  if (p.includes("nvidia") || p.includes("parakeet")) {
    return <NvidiaIcon size={size} />;
  }
  if (p.includes("moonshot") || p.includes("kimi")) {
    return <MoonshotIcon size={size} />;
  }
  if (p.includes("elevenlabs") || p.includes("scribe")) {
    return <ElevenLabsIcon size={size} />;
  }
  if (p.includes("deepgram") || p.includes("nova")) {
    return <DeepgramIcon size={size} />;
  }
  return <Cpu size={size} className="text-white/40" />;
}
